retrieval.cypher:
MATCH (s:PlantItem {tag: "TK-6-2"}), (t:PlantItem {tag: "V-6-5"})
RETURN s.tag AS source_tag, t.tag AS target_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*1..]->(t)
         WHERE all(n IN nodes(p) WHERE coalesce(n.tag, "") <> "GV-6-7")
       } AS can_flow

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "P-9-10"})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
